  "guide/pillar-gap-ja": {
    eyebrow: "일주 사전",
    title: "갑자(甲子) 일주",
    summary: "일간 甲, 일지 子인 날의 일주 갑자(甲子)를 사주링크가 어떻게 읽는지 — 일지가 품은 천간이 일간에게 무엇인지를 계산 규칙 그대로 풀었습니다.",
    backLabel: "계산 근거",
    sections: [
      {
        title: "갑자(甲子)는 육십갑자의 1번째 일주입니다",
        blocks: [
          {
            p: "태어난 날의 간지가 갑자(甲子)이면 일간은 甲(갑, 목(木) 양(陽)), 일지는 子(자, 쥐띠)입니다. 육십갑자에서는 1번째 조합입니다."
          },
          {
            p: "사주링크는 일간이 甲인 분을 「갑목(甲木)」이라고 부르고, 결과 화면에 붙는 한 줄은 이렇습니다. 「곧게 자라는 큰 나무입니다. 방향이 정해지면 흔들리지 않고, 굽히기보다 버티는 쪽을 택합니다.」 이 문구는 아래 읽기와 점수의 계산에는 영향을 주지 않습니다."
          }
        ]
      },
      {
        title: "일지 子가 품은 천간은 일간에게 무엇인가",
        blocks: [
          {
            p: "일지는 배우자 자리입니다. 子가 품은 천간을 일간 甲 기준의 십신으로 읽으면 아래와 같습니다. 본기인 계(癸)가 그 지지의 대표 기운입니다."
          },
          {
            table: {
              caption: "갑자(甲子)의 일지 지장간",
              head: [
                "지장간",
                "자리",
                "지분",
                "일간 甲에게"
              ],
              rows: [
                [
                  "임(壬)",
                  "여기(餘氣)",
                  "{hidJaYeo}",
                  "편인(偏印)"
                ],
                [
                  "계(癸)",
                  "본기(本氣)",
                  "{hidJaBon}",
                  "정인(正印)"
                ]
              ]
            }
          }
        ]
      },
      {
        title: "배우자 자리와 이 일주",
        blocks: [
          {
            p: "전통 명리는 배우자 자리를 남성에게는 정재(正財), 여성에게는 정관(正官)으로 봅니다. 일간이 甲이면 정재는 己, 정관은 辛입니다."
          },
          {
            p: "남성 기준 배우자 자리(정재)는 己입니다. 子의 지장간에는 己가 들어 있지 않습니다."
          },
          {
            p: "여성 기준 배우자 자리(정관)는 辛입니다. 子의 지장간에는 辛이 들어 있지 않습니다."
          }
        ]
      },
      {
        title: "이웃한 일주와 구성 글자",
        blocks: [
          {
            p: "육십갑자에서 앞 일주는 [계해(癸亥)](/guide/pillar-gye-hae), 다음 일주는 [을축(乙丑)](/guide/pillar-eul-chuk)입니다."
          },
          {
            p: "구성 글자는 [갑(甲)](/guide/stem-gap)과 [자(子)](/guide/branch-ja)입니다."
          }
        ]
      },
      {
        kind: "note",
        title: "이 풀이가 말하지 않는 것",
        blocks: [
          {
            ul: [
              "일주 하나로 사람이나 관계를 단정하지 않습니다. 사주는 네 기둥 여덟 글자가 서로 맺는 관계로 읽습니다.",
              "배우자 자리의 읽기는 전통 명리의 규칙을 옮긴 것이며, 성별을 밝히지 않으시면 이 자리는 읽지 않습니다."
            ]
          }
        ]
      }
    ]
  },

